// Verify shared admin secret header
const expectedSecret = $env.ORVEN_ADMIN_SECRET || 'secret-admin-token-12345';
const headers = $input.first().json.headers || {};
const token = headers['x-admin-token'] || headers['X-Admin-Token'];

if (!token || token !== expectedSecret) {
  throw new NodeApiError(this.getNode(), { message: 'Unauthorized: Invalid or missing x-admin-token header' }, { httpCode: '401' });
}

const body = $input.first().json.body || {};
return [{
  json: {
    sessionId: body.sessionId || `sess_${Date.now()}`,
    message: body.message || '',
    timestamp: new Date().toISOString()
  }
}];

